def is_regular_bracket_sequence(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
    return not stack

def find_shortest_regular_bracket_sequence(s, t):
    # Find the longest common subsequence of s and t
    n, m = len(s), len(t)
    dp = [["" for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + s[i - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], key=len)

    lcs = dp[n][m]

    # Construct the result by merging s and t around the longest common subsequence
    result = []
    i, j = 0, 0
    for char in lcs:
        while i < n and s[i] != char:
            result.append(s[i])
            i += 1
        while j < m and t[j] != char:
            result.append(t[j])
            j += 1
        result.append(char)
        i += 1
        j += 1

    result.extend(s[i:])
    result.extend(t[j:])

    return ''.join(result)

